def area_do_curso(titulo, categorias=(), centro=()):
    alvo = " ".join([titulo, *categorias])
    for a in AREAS:
        if re.search(a["padrao"], titulo, re.I):
            return a
    for a in AREAS:
        if re.search(a["padrao"], alvo, re.I):
            return a
    for c in centro:
        if c in GENERICA_POR_CENTRO:
            return next(a for a in AREAS if a["id"] == GENERICA_POR_CENTRO[c])
    return next(a for a in AREAS if a["id"] == "administracao")


def modalidade_do_curso(modalidade, titulo="", categorias=()):
    # O campo oficial "Modalidade" do site manda; título e categorias só desempatam.
    # Exceção: preparatórios aparecem como "Cursos Livres", mas o objetivo de carreira é outro.
    if re.match(r"(?i)preparat[oó]rio|curso preparat", titulo):
        return next(m for m in MODALIDADES if m["id"] == "preparatorio")
    for alvo in (modalidade or "", " ".join([titulo, *categorias])):
        for m in MODALIDADES:
            if alvo and re.search(m["padrao"], alvo, re.I):
                return m
    return MODALIDADES[-1]
